<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Click the Target</title>
    <style>
        canvas {
            display: block;
            margin: 20px auto;
            border: 1px solid #000;
        }
        button {
            display: block;
            margin: 20px auto;
            padding: 10px 20px;
            font-size: 20px;
            cursor: pointer;
        }
        #score {
            margin-bottom: 20px;
            font-size: 24px;
            text-align: center;
        }
        #timer {
            font-size: 36px;
            text-align: center;
        }
        #gameOver {
            display: none;
            margin: 20px auto;
            padding: 10px 20px;
            font-size: 24px;
            border: 1px solid #ccc;
            background-color: #f8f9fa;
            color: #333;
        }
    </style>
</head>
<body>
    <button id="startButton">Start</button>
    <canvas id="gameCanvas" width="600" height="400"></canvas>
    <div id="score" class="hidden">Score: 0</div>
    <div id="timer" class="hidden">30s remaining</div>
    <div id="gameOver" class="hidden">Game Over! Final Score: 0</div>

    <script>
        const canvas = document.getElementById('gameCanvas');
        const ctx = canvas.getContext('2d');
        const startButton = document.getElementById('startButton');
        const scoreElement = document.getElementById('score');
        const timerElement = document.getElementById('timer');
        const gameOverElement = document.getElementById('gameOver');

        let isGameOver = false;
        let score = 0;
        let targetPositions = [];
        let startTime;

        function createTarget() {
            if (targetPositions.length < 10) {
                const x = Math.floor(Math.random() * canvas.width);
                const y = Math.floor(Math.random() * canvas.height);
                targetPositions.push({ position: [x, y] });

                const circle = new Circle(canvas.width, canvas.height, 20);
                canvas.appendChild(circle);
            }
        }

        function draw() {
            ctx.clearRect(0, 0, canvas.width, canvas.height);

            if (!isGameOver) {
                scoreElement.textContent = score;
                timerElement.textContent = `30s remaining`;

                targetPositions.forEach((pos) => {
                    ctx.beginPath();
                    ctx.arc(pos.position[0], pos.position[1], 10, 0, Math.PI * 2);
                    ctx.fillStyle = 'red';
                    ctx.fill();
                });
            } else {
                gameOverElement.textContent = `Game Over! Final Score: ${score}`;
            }

            ctx.drawImage(canvas, 0, 0);
        }

        function startGame() {
            isGameOver = false;
            score = 0;
            targetPositions = [];
            startTime = Date.now();
            createTarget();
            setInterval(draw, 1000 / 60); // Update every 60th of a second
        }

        startButton.addEventListener('click', startGame);

        function handleClick(event) {
            const rect = canvas.getBoundingClientRect();
            const x = event.clientX - rect.left;
            const y = event.clientY - rect.top;

            targetPositions.forEach((pos) => {
                if (
                    pos.position[0] === Math.floor(x) &&
                    pos.position[1] === Math.floor(y)
                ) {
                    score++;
                    return true; // Exit the loop
                }
            });
        }

        canvas.addEventListener('click', handleClick);
    </script>
</body>
</html>
